import { describe, expect, it } from 'vitest';
import { convertMenksoftToUnicode } from '../../src/menksoft/convert.js';

// Generated by script from mongol_code (CC0, suragch) test/menkuni_general_test.dart.
// Each row: [test name, Menksoft input, expected Unicode].
const cases: [name: string, menksoft: string, expected: string][] = [
  ['emptyString', '', ''],
  ['spaceChar', ' ', ' '],
  [
    'englishKeyboardChars',
    'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890!@#$%^&*()-=_+`~;:\'" ,./<>?',
    'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ1234567890!@#$%^&*()-=_+`~;:\'" ,./<>?',
  ],
  ['chineseChars', '\u4E2D\u6587', '\u4E2D\u6587'],
  [
    'emojiChars',
    '\uD83D\uDE04\uD83D\uDD90\uD83C\uDFFC\uD83C\uDDF3\uD83C\uDDF4',
    '\uD83D\uDE04\uD83D\uDD90\uD83C\uDFFC\uD83C\uDDF3\uD83C\uDDF4',
  ],
  ['unicodeString', 'ᠮᠤᠩᠭᠤᠯ', 'ᠮᠤᠩᠭᠤᠯ'],
];

describe('Menksoft -> Unicode: non-Menksoft strings', () => {
  it.each(cases)('%s', (_name, menksoft, expected) => {
    expect(convertMenksoftToUnicode(menksoft)).toBe(expected);
  });
});
